    29	export class ParksPage {
    30	  /** Bound from the route by withComponentInputBinding; undefined on /parks. */
    31	  readonly id = input<string>();
    32	
    33	  private readonly parksService = inject(ParksService);
    34	  private readonly router = inject(Router);
    35	  protected readonly parks = this.parksService.parks;
    36	  protected readonly loading = this.parksService.loading;
    37	  protected readonly error = this.parksService.error;
    38	
    39	  /** Selecting a park expands the sheet, the list collapses it; the toggle overrides until the next navigation. */
    40	  protected readonly expanded = linkedSignal({
    41	    source: this.id,
    42	    computation: (id) => id !== undefined,
    43	  });
    44	  protected readonly isMobile = signal(false);
    45	  private readonly sheetHeight = signal(0);
    46	  protected readonly centerOffset = computed(() => (this.isMobile() ? this.sheetHeight() : 0));
    47	
    48	  private readonly sheet = viewChild.required<ElementRef<HTMLElement>>('sheet');
    49	
    50	  constructor() {
    51	    const destroyRef = inject(DestroyRef);
    52	
    53	    if (typeof matchMedia === 'function') {
    54	      const query = matchMedia(MOBILE_QUERY);
    55	      this.isMobile.set(query.matches);
    56	      const onChange = (event: MediaQueryListEvent): void => this.isMobile.set(event.matches);
    57	      query.addEventListener('change', onChange);
    58	      destroyRef.onDestroy(() => query.removeEventListener('change', onChange));
    59	    }
    60	
    61	    afterNextRender(() => {
    62	      if (typeof ResizeObserver === 'undefined') {
    63	        return;
    64	      }
    65	      const observer = new ResizeObserver((entries) => {
    66	        for (const entry of entries) {
    67	          this.sheetHeight.set(entry.contentRect.height);
    68	        }
    69	      });
    70	      observer.observe(this.sheet().nativeElement);
    71	      destroyRef.onDestroy(() => observer.disconnect());
    72	    });
    73	  }
    74	
    75	  protected toggleSheet(): void {
    76	    this.expanded.update((value) => !value);
    77	  }
    78	
    79	  /** A marker reached by Tab must not sit behind the expanded sheet. */
    80	  protected onMapFocusIn(): void {
    81	    if (this.isMobile()) {
    82	      this.expanded.set(false);
    83	    }
    84	  }
    85	
    86	  protected onSelect(id: string): void {
    87	    void this.router.navigate(['/parks', id]);
    88	  }
    89	}
