=== map/park-map.ts
     1	import {
     2	  ChangeDetectionStrategy,
     3	  Component,
     4	  DestroyRef,
     5	  ElementRef,
     6	  ViewEncapsulation,
     7	  afterNextRender,
     8	  effect,
     9	  inject,
    10	  input,
    11	  output,
    12	  signal,
    13	  viewChild,
    14	} from '@angular/core';
    15	import {
    16	  LeafletKeyboardEvent,
    17	  Map as LeafletMap,
    18	  Marker,
    19	  divIcon,
    20	  latLngBounds,
    21	  map,
    22	  marker,
    23	  tileLayer,
    24	} from 'leaflet';
    25	import { Park } from '../data/park';
    26	
    27	const SELECTED_Z_OFFSET = 1000;
    28	
    29	const pinIcon = divIcon({
    30	  className: 'park-pin',
    31	  html:
    32	    '<svg aria-hidden="true" width="28" height="40" viewBox="0 0 28 40">' +
    33	    '<path fill="currentColor" d="M14 0C6.3 0 0 6.3 0 14c0 10.5 14 26 14 26s14-15.5 14-26C28 6.3 21.7 0 14 0zm0 19a5 5 0 1 1 0-10 5 5 0 0 1 0 10z"/>' +
    34	    '</svg>',
    35	  iconSize: [28, 40],
    36	  iconAnchor: [14, 40],
    37	  tooltipAnchor: [0, -36],
    38	});
    39	
    40	@Component({
    41	  selector: 'app-park-map',
    42	  templateUrl: './park-map.html',
    43	  styleUrl: './park-map.css',
    44	  changeDetection: ChangeDetectionStrategy.OnPush,
    45	  encapsulation: ViewEncapsulation.None,
    46	  host: { class: 'park-map' },
    47	})
    48	export class ParkMap {
    49	  readonly parks = input.required<Park[]>();
    50	  readonly selectedId = input<string | undefined>();
    51	  readonly centerOffset = input(0);
    52	  readonly select = output<string>();
    53	
    54	  private readonly container = viewChild.required<ElementRef<HTMLDivElement>>('container');
    55	  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
    56	  private readonly leafletMap = signal<LeafletMap | undefined>(undefined);
    57	  private readonly markers = signal<Map<string, Marker>>(new Map());
    58	  private selectedMarker: Marker | undefined;
    59	
    60	  constructor() {
    61	    const destroyRef = inject(DestroyRef);
    62	
    63	    afterNextRender(() => {
    64	      const leafletMap = map(this.container().nativeElement);
    65	      leafletMap.attributionControl.setPosition('topright');
    66	      tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    67	        maxZoom: 19,
    68	        attribution:
    69	          '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    70	      }).addTo(leafletMap);
    71	      leafletMap.invalidateSize();
    72	
    73	      const observer =
    74	        typeof ResizeObserver !== 'undefined'
    75	          ? new ResizeObserver(() => leafletMap.invalidateSize())
    76	          : undefined;
    77	      observer?.observe(this.host.nativeElement);
    78	
    79	      destroyRef.onDestroy(() => {
    80	        observer?.disconnect();
    81	        leafletMap.remove();
    82	      });
    83	      this.leafletMap.set(leafletMap);
    84	    });
    85	
    86	    effect((onCleanup) => {
    87	      const leafletMap = this.leafletMap();
    88	      if (!leafletMap) {
    89	        return;
    90	      }
    91	      const markers = this.buildMarkers(leafletMap, this.parks());
    92	      this.markers.set(markers);
    93	      onCleanup(() => markers.forEach((m) => m.remove()));
    94	    });
    95	
    96	    effect(() => {
    97	      const leafletMap = this.leafletMap();
    98	      const markers = this.markers();
    99	      const selected = markers.get(this.selectedId() ?? '');
   100	      const offset = this.centerOffset();
   101	      if (!leafletMap || markers.size === 0) {
   102	        return;
   103	      }
   104	      this.moveCamera(leafletMap, markers, selected, offset);
   105	      this.markSelected(selected);
   106	    });
   107	  }
   108	
   109	  private buildMarkers(leafletMap: LeafletMap, parks: Park[]): Map<string, Marker> {
   110	    const markers = new Map<string, Marker>();
   111	    for (const park of parks) {
   112	      if (!park.coordinates) {
   113	        continue;
   114	      }
   115	      const label = document.createElement('span');
   116	      label.textContent = park.name;
   117	      const m = marker(park.coordinates, {
   118	        icon: pinIcon,
   119	        title: park.name,
   120	        alt: park.name,
   121	        keyboard: true,
   122	      }).bindTooltip(label, { direction: 'top' });
   123	      // Leaflet adds a marker only once the map has a view, so the element is labelled on add.
   124	      m.on('add', () => m.getElement()?.setAttribute('aria-label', park.name));
   125	      m.on('click', () => this.select.emit(park.id));
   126	      // Leaflet maps Enter to click only for markers with a popup, so handle it here.
   127	      m.on('keypress', (e: LeafletKeyboardEvent) => {
   128	        if (e.originalEvent.keyCode === 13) {
   129	          this.select.emit(park.id);
   130	        }
   131	      });
   132	      m.addTo(leafletMap);
   133	      markers.set(park.id, m);
   134	    }
   135	    return markers;
   136	  }
   137	
   138	  private moveCamera(
   139	    leafletMap: LeafletMap,
   140	    markers: Map<string, Marker>,
   141	    selected: Marker | undefined,
   142	    offset: number,
   143	  ): void {
   144	    const animate = !(
   145	      typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
   146	    );
   147	    if (selected) {
   148	      const point = leafletMap.project(selected.getLatLng(), 15).add([0, offset / 2]);
   149	      leafletMap.setView(leafletMap.unproject(point, 15), 15, { animate });
   150	    } else {
   151	      const bounds = latLngBounds([...markers.values()].map((m) => m.getLatLng()));
   152	      leafletMap.fitBounds(bounds, {
   153	        padding: [24, 24],
   154	        paddingBottomRight: [24, 24 + offset],
   155	        animate,
   156	      });
   157	    }
   158	  }
   159	
   160	  private markSelected(selected: Marker | undefined): void {
   161	    if (this.selectedMarker && this.selectedMarker !== selected) {
   162	      this.selectedMarker.getElement()?.classList.remove('is-selected');
   163	      this.selectedMarker.getElement()?.removeAttribute('aria-current');
   164	      this.selectedMarker.setZIndexOffset(0);
   165	    }
   166	    selected?.getElement()?.classList.add('is-selected');
   167	    selected?.getElement()?.setAttribute('aria-current', 'true');
   168	    selected?.setZIndexOffset(SELECTED_Z_OFFSET);
   169	    this.selectedMarker = selected;
   170	  }
   171	}
