    20	  styleUrl: './park-panel.css',
    21	  changeDetection: ChangeDetectionStrategy.OnPush,
    22	})
    23	export class ParkPanel {
    24	  readonly parks = input.required<Park[]>();
    25	  readonly loading = input.required<boolean>();
    26	  readonly error = input.required<string | null>();
    27	  /** Undefined means list mode. */
    28	  readonly selectedId = input<string>();
    29	
    30	  protected readonly selected = computed(() => {
    31	    const id = this.selectedId();
    32	    return id === undefined ? undefined : this.parks().find((park) => park.id === id);
    33	  });
    34	
    35	  private readonly listHeading = viewChild<ElementRef<HTMLHeadingElement>>('listHeading');
    36	  private readonly detailsHeading = viewChild<ElementRef<HTMLHeadingElement>>('detailsHeading');
    37	  private readonly parkLinks = viewChildren<ElementRef<HTMLAnchorElement>>('parkLink');
    38	
    39	  /** The id the focus effect last acted on; plain fields so writing them never re-runs it. */
    40	  private lastFocusedId: string | undefined;
    41	  /** The park whose link gets focus back when the list returns. */
    42	  private lastOpenedId: string | undefined;
    43	
    44	  constructor() {
    45	    afterRenderEffect(() => {
    46	      const id = this.selectedId();
    47	      const detailsHeading = this.detailsHeading();
    48	      const listHeading = this.listHeading();
    49	      const links = this.parkLinks();
    50	
    51	      if (id !== undefined) {
    52	        if (id !== this.lastFocusedId && detailsHeading) {
    53	          detailsHeading.nativeElement.focus();
    54	          this.lastFocusedId = id;
    55	          this.lastOpenedId = id;
    56	        }
    57	        return;
    58	      }
    59	
    60	      // Back in list mode after a details view: wait until loading is over, then restore focus.
    61	      if (this.lastFocusedId === undefined || untracked(this.loading)) {
    62	        return;
    63	      }
    64	      const link = links.find((ref) => ref.nativeElement.dataset['parkId'] === this.lastOpenedId);
    65	      const target = link?.nativeElement ?? listHeading?.nativeElement;
    66	      if (target) {
    67	        target.focus();
    68	        this.lastFocusedId = undefined;
    69	      }
    70	    });
    71	  }
    72	}
